<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class AdmissionController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->canDo('students.manage'),403);}
 public function index(Request $r){$this->ok($r);$q=DB::table('admission_applicants as a')->leftJoin('study_groups as g','g.id','=','a.target_group_id')->select('a.*','g.name as group_name');if($r->filled('q')){$s='%'.$r->q.'%';$q->where(fn($x)=>$x->where('a.last_name','like',$s)->orWhere('a.first_name','like',$s)->orWhere('a.document_number','like',$s));}if($r->filled('status'))$q->where('a.status',$r->status);return view('admission.index',['rows'=>$q->orderByDesc('a.average_score')->orderBy('a.last_name')->paginate(100)->withQueryString(),'groups'=>DB::table('study_groups')->where('active',1)->orderBy('name')->get()]);}
 public function store(Request $r){$this->ok($r);$d=$this->data($r);DB::table('admission_applicants')->insert($d+['status'=>'submitted','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Абитуриент добавлен');}
 public function update(Request $r,$id){$this->ok($r);abort_unless(DB::table('admission_applicants')->where('id',$id)->exists(),404);$d=$this->data($r);$d['status']=$r->validate(['status'=>'required|in:draft,submitted,verified,recommended,rejected,enrolled'])['status'];DB::table('admission_applicants')->where('id',$id)->update($d+['updated_at'=>now()]);return back()->with('success','Заявление обновлено');}
 public function enroll(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');abort_if(!$p,422,'Не выбран учебный период.');PeriodGuard::writable($p->id);$d=$r->validate(['applicant_ids'=>'required|array|min:1','applicant_ids.*'=>'integer|exists:admission_applicants,id','target_group_id'=>'required|exists:study_groups,id','order_number'=>'required|string|max:100','order_date'=>'required|date','effective_on'=>'required|date','basis'=>'nullable|string|max:5000']);DB::transaction(function()use($r,$p,$d){$order=DB::table('academic_orders')->insertGetId(['academic_period_id'=>$p->id,'number'=>$d['order_number'],'order_date'=>$d['order_date'],'student_id'=>null,'type'=>'enrollment','title'=>'Зачисление абитуриентов','basis'=>$d['basis']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);foreach($d['applicant_ids'] as $aid){$a=DB::table('admission_applicants')->where('id',$aid)->lockForUpdate()->first();if(!$a||$a->student_id)continue;$sid=DB::table('students')->insertGetId(['last_name'=>$a->last_name,'first_name'=>$a->first_name,'middle_name'=>$a->middle_name,'current_group_id'=>$d['target_group_id'],'status'=>'active','enrolled_on'=>$d['effective_on'],'created_at'=>now(),'updated_at'=>now()]);DB::table('student_group_memberships')->insert(['student_id'=>$sid,'academic_period_id'=>$p->id,'study_group_id'=>$d['target_group_id'],'starts_on'=>$d['effective_on'],'status'=>'active','created_at'=>now(),'updated_at'=>now()]);DB::table('student_movements')->insert(['student_id'=>$sid,'academic_period_id'=>$p->id,'type'=>'enrollment','from_group_id'=>null,'to_group_id'=>$d['target_group_id'],'effective_on'=>$d['effective_on'],'academic_order_id'=>$order,'order_number'=>$d['order_number'],'order_date'=>$d['order_date'],'basis'=>$d['basis']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('admission_applicants')->where('id',$aid)->update(['status'=>'enrolled','target_group_id'=>$d['target_group_id'],'student_id'=>$sid,'updated_at'=>now()]);}});return redirect()->route('academic.movements')->with('success','Абитуриенты зачислены и переведены в контингент');}
 private function data(Request $r){return $r->validate(['last_name'=>'required|string|max:100','first_name'=>'required|string|max:100','middle_name'=>'nullable|string|max:100','birth_date'=>'nullable|date','phone'=>'nullable|string|max:100','email'=>'nullable|email|max:255','document_number'=>'nullable|string|max:100','specialty'=>'nullable|string|max:255','education_base'=>'nullable|string|max:50','average_score'=>'nullable|numeric|min:0|max:5','target_group_id'=>'nullable|exists:study_groups,id','note'=>'nullable|string|max:5000']);}
}